import pandas as pd
import pdfplumber

# Extract from PDF
pdf_rows = []
header = None
with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            for row in table:
                if row and row[0] == 'ID':
                    header = row
                    continue
                if row and row[0] and row[0].startswith('EMP'):
                    pdf_rows.append(row)

print(f'Header: {header}')
print(f'PDF rows: {len(pdf_rows)}')

pdf_df = pd.DataFrame(pdf_rows, columns=header)
print(pdf_df.head())

# Normalize PDF types
def parse_salary(s):
    return int(str(s).replace(',', '').strip())

pdf_df['Salary'] = pdf_df['Salary'].apply(parse_salary)
pdf_df['Years'] = pdf_df['Years'].astype(int)
pdf_df['Score'] = pdf_df['Score'].astype(float)

# Load Excel
xl_df = pd.read_excel('/root/employees_current.xlsx')
print(f'Excel rows: {len(xl_df)}')

pdf_map = {r['ID']: r for _, r in pdf_df.iterrows()}
xl_map = {r['ID']: r for _, r in xl_df.iterrows()}

pdf_ids = set(pdf_map.keys())
xl_ids = set(xl_map.keys())

deleted = sorted(pdf_ids - xl_ids)
print(f'Deleted: {len(deleted)}')

fields_numeric = {'Salary', 'Years'}
fields_float = {'Score'}
text_fields = {'First', 'Last', 'Dept', 'Position', 'Location'}
all_fields = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

modified = []
for eid in sorted(pdf_ids & xl_ids):
    old = pdf_map[eid]
    new = xl_map[eid]
    for f in all_fields:
        ov = old[f]
        nv = new[f]
        if f in fields_numeric:
            ov = int(ov); nv = int(nv)
            if ov != nv:
                modified.append({'id': eid, 'field': f, 'old_value': ov, 'new_value': nv})
        elif f in fields_float:
            ov = float(ov); nv = float(nv)
            if ov != nv:
                modified.append({'id': eid, 'field': f, 'old_value': ov, 'new_value': nv})
        else:
            ov = str(ov).strip(); nv = str(nv).strip()
            if ov != nv:
                modified.append({'id': eid, 'field': f, 'old_value': ov, 'new_value': nv})

modified.sort(key=lambda x: x['id'])
print(f'Modified: {len(modified)}')
print('Sample modified:', modified[:5])
print('Sample deleted:', deleted[:5])

result = {'deleted_employees': deleted, 'modified_employees': modified}
with open('/root/diff_report.json', 'w') as f:
    json.dump(result, f, indent=2)
print('Saved.')
